import{_ as e,o as a,c as i,a8 as n}from"./chunks/framework.DB1tY2mn.js";const p=JSON.parse('{"title":"Untitled string in Mermaid Config Schema","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/schemas/config.schema.yaml","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/config/schema-docs/config-properties-elk-properties-layeringstrategy.html"}]]},"headers":[],"relativePath":"config/schema-docs/config-properties-elk-properties-layeringstrategy.md","filePath":"config/schema-docs/config-properties-elk-properties-layeringstrategy.md"}'),s={name:"config/schema-docs/config-properties-elk-properties-layeringstrategy.md"};function l(o,t,r,d,g,c){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="untitled-string-in-mermaid-config-schema" tabindex="-1">Untitled string in Mermaid Config Schema <a class="header-anchor" href="#untitled-string-in-mermaid-config-schema" aria-label="Permalink to &quot;Untitled string in Mermaid Config Schema&quot;">​</a></h1><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/layeringStrategy</span></span></code></pre></div><p>Elk specific option deciding which layer each node is assigned to — the column in a left-to-right diagram, the row in a top-down one. This is the coarsest of the three placement decisions, so changing it moves nodes further than anything else short of altering spacing.</p><p>NETWORK_SIMPLEX aims for the fewest long edges. LONGEST_PATH pushes every node as late as it can go. COFFMAN_GRAHAM bounds how many nodes share a layer, giving a more even, block-like shape on wide graphs. MIN_WIDTH and STRETCH_WIDTH trade edge length for a narrower or wider drawing. INTERACTIVE honours positions already on the nodes.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Abstract</th><th style="text-align:left;">Extensible</th><th style="text-align:left;">Status</th><th style="text-align:left;">Identifiable</th><th style="text-align:left;">Custom Properties</th><th style="text-align:left;">Additional Properties</th><th style="text-align:left;">Access Restrictions</th><th style="text-align:left;">Defined In</th></tr></thead><tbody><tr><td style="text-align:left;">Can be instantiated</td><td style="text-align:left;">No</td><td style="text-align:left;">Unknown status</td><td style="text-align:left;">Unknown identifiability</td><td style="text-align:left;">Forbidden</td><td style="text-align:left;">Allowed</td><td style="text-align:left;">none</td><td style="text-align:left;"><a href="/dochub/mermaid/schemas/config.schema.json" title="open original schema">config.schema.json*</a></td></tr></tbody></table><h2 id="layeringstrategy-type" tabindex="-1">layeringStrategy Type <a class="header-anchor" href="#layeringstrategy-type" aria-label="Permalink to &quot;layeringStrategy Type&quot;">​</a></h2><p><code>string</code></p><h2 id="layeringstrategy-constraints" tabindex="-1">layeringStrategy Constraints <a class="header-anchor" href="#layeringstrategy-constraints" aria-label="Permalink to &quot;layeringStrategy Constraints&quot;">​</a></h2><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;NETWORK_SIMPLEX&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LONGEST_PATH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;LONGEST_PATH_SOURCE&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;COFFMAN_GRAHAM&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;MIN_WIDTH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;STRETCH_WIDTH&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;INTERACTIVE&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table>',10)])])}const y=e(s,[["render",l]]);export{p as __pageData,y as default};
